/* ============================================================
   Steelbook design tokens
   generated — do not hand-edit
   Source: Figma "Steelbook Design System" variable collections
     · Primitives (86)          · Color (56, Light/Dark)
     · Layout (21)              · Text (48, Desktop/Mobile)
   Exported 2026-08-19 via Figma MCP; will be emitted by the
   Style Dictionary pipeline once it lands.

   Responsive typography: the Text collection's Desktop and
   Mobile modes differ only in font size, and only for the
   display and heading tiers — body, label and mono are
   identical in both (16px body stays 16px; shrinking it hurts
   readability and trips iOS input auto-zoom). Because Figma's
   per-mode line-heights and tracking were derived from the same
   ratios, the unitless line-height and em tracking values are
   identical across modes and need no override — only the seven
   size tokens flip.

   BREAKPOINT: 768px. Mobile mode below it, Desktop at and
   above. Figma holds no variable for this number, so this file
   is its source of truth.

   NOT machine-readable — carried by hand, recorded in each text
   style's description in Figma:
     · font family and weight (fontName is not bound)
     · the Archivo width axis (wdth), which the Plugin API does
       not expose at all. Width stays at its desktop value on
       mobile; Figma cannot hold it per mode, so varying it
       here would put a design decision in CSS alone.
   If you change any of those in Figma, change them here too;
   nothing will catch the drift.

   Font loading — Archivo MUST load as a variable font or the
   width axis silently does nothing:
   https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@62..125,100..900&family=JetBrains+Mono:wght@400..700&display=swap
   ============================================================ */

:root {
  /* ---------- Primitives · color ---------- */
  --sb-white: #ffffff;
  --sb-black: #000000;

  --sb-gray-50: #fafafa;
  --sb-gray-100: #f4f4f4;
  --sb-gray-200: #e4e4e4;
  --sb-gray-300: #d4d4d4;
  --sb-gray-400: #a3a3a3;
  --sb-gray-500: #737373;
  --sb-gray-600: #525252;
  --sb-gray-700: #3f3f3f;
  --sb-gray-800: #262626;
  --sb-gray-900: #171717;
  --sb-gray-950: #0a0a0a;

  --sb-orange-50: #fff3ec;
  --sb-orange-100: #ffe3d3;
  --sb-orange-200: #ffc5a6;
  --sb-orange-300: #ffa070;
  --sb-orange-400: #ff7433;
  --sb-orange-500: #ff4d00;
  --sb-orange-600: #e04400;
  --sb-orange-700: #b03600;
  --sb-orange-800: #8f2c00;
  --sb-orange-900: #661f00;

  --sb-red-100: #ffdfdc;
  --sb-red-300: #ff7a70;
  --sb-red-500: #f42b1d;
  --sb-red-700: #b51309;
  --sb-red-900: #7a0f08;

  --sb-green-100: #d9fbe3;
  --sb-green-300: #4ade80;
  --sb-green-500: #00c853;
  --sb-green-700: #03813a;
  --sb-green-900: #005a24;

  --sb-yellow-100: #fff8c2;
  --sb-yellow-300: #ffe454;
  --sb-yellow-500: #ffd600;
  --sb-yellow-700: #8a6d00;
  --sb-yellow-900: #5c4a00;

  --sb-blue-100: #d8e9ff;
  --sb-blue-300: #6fa8ff;
  --sb-blue-500: #0866ff;
  --sb-blue-700: #0b4ecc;
  --sb-blue-900: #032e7a;

  --sb-alpha-black-5: rgba(0, 0, 0, 0.05);
  --sb-alpha-black-10: rgba(0, 0, 0, 0.1);
  --sb-alpha-black-20: rgba(0, 0, 0, 0.2);
  --sb-alpha-black-60: rgba(0, 0, 0, 0.6);
  --sb-alpha-white-10: rgba(255, 255, 255, 0.1);
  --sb-alpha-white-20: rgba(255, 255, 255, 0.2);
  --sb-alpha-white-70: rgba(255, 255, 255, 0.7);

  /* ---------- Primitives · space ---------- */
  --sb-space-0: 0px;
  --sb-space-1: 4px;
  --sb-space-2: 8px;
  --sb-space-3: 12px;
  --sb-space-4: 16px;
  --sb-space-5: 20px;
  --sb-space-6: 24px;
  --sb-space-8: 32px;
  --sb-space-10: 40px;
  --sb-space-12: 48px;
  --sb-space-14: 56px;
  --sb-space-16: 64px;
  --sb-space-20: 80px;
  --sb-space-24: 96px;
  --sb-space-32: 128px;

  /* ---------- Primitives · radius & border ---------- */
  --sb-radius-none: 0px;
  --sb-radius-full: 999px;
  --sb-border-1: 1px;
  --sb-border-2: 2px;
  --sb-border-3: 3px;

  /* ---------- Primitives · shadow offset ----------
     Figma: Primitives › shadow/offset-* (mode-invariant), bound into the
     offsetX and offsetY of effect styles shadow/hard-sm · -md · -lg. The
     shadows are hard: one offset drives both axes, with no blur or spread. */
  --sb-shadow-offset-sm: 3px;
  --sb-shadow-offset-md: 6px;
  --sb-shadow-offset-lg: 10px;

  /* ---------- Primitives · font size ----------
     Figma: Primitives › font-size/* (mode-invariant) */
  --sb-font-size-12: 12px;
  --sb-font-size-14: 14px;
  --sb-font-size-16: 16px;
  --sb-font-size-18: 18px;
  --sb-font-size-20: 20px;
  --sb-font-size-24: 24px;
  --sb-font-size-28: 28px;
  --sb-font-size-32: 32px;
  --sb-font-size-40: 40px;
  --sb-font-size-44: 44px;
  --sb-font-size-56: 56px;
  --sb-font-size-72: 72px;
  --sb-font-size-96: 96px;

  /* ---------- Primitives · font family ----------
     Hand-carried (fontName is not bound in Figma). Fallback
     stacks are additions; the first name in each is the Figma
     value verbatim. */
  --sb-font-family-sans: 'Archivo', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --sb-font-family-mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace;

  /* ---------- Primitives · font weight ----------
     Hand-carried. Figma style names → numeric weights. */
  --sb-font-weight-regular: 400;
  --sb-font-weight-semibold: 600;
  --sb-font-weight-bold: 700;
  --sb-font-weight-black: 900;

  /* ---------- Primitives · font width (Archivo wdth axis) ----------
     Hand-carried — the Plugin API cannot read this. Consumed via
     font-stretch. Archivo's axis runs 62–125; JetBrains Mono has
     no width axis, so mono styles omit width. */
  --sb-font-width-normal: 100%;
  --sb-font-width-105: 105%;
  --sb-font-width-110: 110%;
  --sb-font-width-120: 120%;
  --sb-font-width-expanded: 125%;

  /* ---------- Primitives · line height ----------
     Ratios derived from Text › <style>/line-height (px) ÷ size.
     Identical in both modes. */
  --sb-line-height-95: 0.95;
  --sb-line-height-100: 1;
  --sb-line-height-105: 1.05;
  --sb-line-height-110: 1.1;
  --sb-line-height-115: 1.15;
  --sb-line-height-120: 1.2;
  --sb-line-height-130: 1.3;
  --sb-line-height-145: 1.45;
  --sb-line-height-150: 1.5;

  /* ---------- Primitives · letter spacing ----------
     Ems derived from Text › <style>/tracking (px) ÷ size.
     Identical in both modes. */
  --sb-tracking-tightest: -0.03em;
  --sb-tracking-tighter: -0.025em;
  --sb-tracking-tight: -0.02em;
  --sb-tracking-snug: -0.015em;
  --sb-tracking-slight: -0.01em;
  --sb-tracking-subtle: -0.005em;
  --sb-tracking-none: 0em;
  --sb-tracking-wide: 0.08em;

  /* ---------- Layout (aliases → primitives) ---------- */
  --sb-gap-2xs: var(--sb-space-1);
  --sb-gap-xs: var(--sb-space-2);
  --sb-gap-sm: var(--sb-space-3);
  --sb-gap-md: var(--sb-space-4);
  --sb-gap-lg: var(--sb-space-6);
  --sb-gap-xl: var(--sb-space-8);
  --sb-gap-2xl: var(--sb-space-12);
  --sb-gap-3xl: var(--sb-space-16);

  --sb-size-control-sm: var(--sb-space-8);
  --sb-size-control-md: var(--sb-space-10);
  --sb-size-control-lg: var(--sb-space-12);
  --sb-size-control-xl: var(--sb-space-14);
  --sb-size-icon-sm: var(--sb-space-4);
  --sb-size-icon-md: var(--sb-space-5);
  --sb-size-icon-lg: var(--sb-space-6);

  --sb-radius-control: var(--sb-radius-none);
  --sb-radius-surface: var(--sb-radius-none);
  --sb-radius-round: var(--sb-radius-full);

  --sb-stroke-thin: var(--sb-border-1);
  --sb-stroke-default: var(--sb-border-2);
  --sb-stroke-heavy: var(--sb-border-3);

  /* ---------- Text styles · Desktop mode ----------
     One group per Figma text style, name-for-name.
     Width tapers as size drops: 125 → 120 → 110 → 105 → 100.
     Sizes are overridden below 768px; everything else holds. */

  /* display/1 — Archivo Black 96 / 0.95 / −0.03em / wdth 125 */
  --sb-text-display-1-family: var(--sb-font-family-sans);
  --sb-text-display-1-weight: var(--sb-font-weight-black);
  --sb-text-display-1-width: var(--sb-font-width-expanded);
  --sb-text-display-1-size: var(--sb-font-size-96);
  --sb-text-display-1-line-height: var(--sb-line-height-95);
  --sb-text-display-1-tracking: var(--sb-tracking-tightest);

  /* display/2 — Archivo Black 72 / 1 / −0.025em / wdth 125 */
  --sb-text-display-2-family: var(--sb-font-family-sans);
  --sb-text-display-2-weight: var(--sb-font-weight-black);
  --sb-text-display-2-width: var(--sb-font-width-expanded);
  --sb-text-display-2-size: var(--sb-font-size-72);
  --sb-text-display-2-line-height: var(--sb-line-height-100);
  --sb-text-display-2-tracking: var(--sb-tracking-tighter);

  /* display/3 — Archivo Black 56 / 1.05 / −0.02em / wdth 125 */
  --sb-text-display-3-family: var(--sb-font-family-sans);
  --sb-text-display-3-weight: var(--sb-font-weight-black);
  --sb-text-display-3-width: var(--sb-font-width-expanded);
  --sb-text-display-3-size: var(--sb-font-size-56);
  --sb-text-display-3-line-height: var(--sb-line-height-105);
  --sb-text-display-3-tracking: var(--sb-tracking-tight);

  /* heading/1 — Archivo Bold 40 / 1.1 / −0.015em / wdth 120 */
  --sb-text-heading-1-family: var(--sb-font-family-sans);
  --sb-text-heading-1-weight: var(--sb-font-weight-bold);
  --sb-text-heading-1-width: var(--sb-font-width-120);
  --sb-text-heading-1-size: var(--sb-font-size-40);
  --sb-text-heading-1-line-height: var(--sb-line-height-110);
  --sb-text-heading-1-tracking: var(--sb-tracking-snug);

  /* heading/2 — Archivo Bold 32 / 1.15 / −0.01em / wdth 110 */
  --sb-text-heading-2-family: var(--sb-font-family-sans);
  --sb-text-heading-2-weight: var(--sb-font-weight-bold);
  --sb-text-heading-2-width: var(--sb-font-width-110);
  --sb-text-heading-2-size: var(--sb-font-size-32);
  --sb-text-heading-2-line-height: var(--sb-line-height-115);
  --sb-text-heading-2-tracking: var(--sb-tracking-slight);

  /* heading/3 — Archivo Bold 24 / 1.2 / −0.005em / wdth 105 */
  --sb-text-heading-3-family: var(--sb-font-family-sans);
  --sb-text-heading-3-weight: var(--sb-font-weight-bold);
  --sb-text-heading-3-width: var(--sb-font-width-105);
  --sb-text-heading-3-size: var(--sb-font-size-24);
  --sb-text-heading-3-line-height: var(--sb-line-height-120);
  --sb-text-heading-3-tracking: var(--sb-tracking-subtle);

  /* heading/4 — Archivo Bold 20 / 1.3 / 0 / wdth 100 */
  --sb-text-heading-4-family: var(--sb-font-family-sans);
  --sb-text-heading-4-weight: var(--sb-font-weight-bold);
  --sb-text-heading-4-width: var(--sb-font-width-normal);
  --sb-text-heading-4-size: var(--sb-font-size-20);
  --sb-text-heading-4-line-height: var(--sb-line-height-130);
  --sb-text-heading-4-tracking: var(--sb-tracking-none);

  /* body/lg — Archivo Regular 18 / 1.5 / 0 (same on mobile) */
  --sb-text-body-lg-family: var(--sb-font-family-sans);
  --sb-text-body-lg-weight: var(--sb-font-weight-regular);
  --sb-text-body-lg-width: var(--sb-font-width-normal);
  --sb-text-body-lg-size: var(--sb-font-size-18);
  --sb-text-body-lg-line-height: var(--sb-line-height-150);
  --sb-text-body-lg-tracking: var(--sb-tracking-none);

  /* body/md — Archivo Regular 16 / 1.5 / 0 (same on mobile) */
  --sb-text-body-md-family: var(--sb-font-family-sans);
  --sb-text-body-md-weight: var(--sb-font-weight-regular);
  --sb-text-body-md-width: var(--sb-font-width-normal);
  --sb-text-body-md-size: var(--sb-font-size-16);
  --sb-text-body-md-line-height: var(--sb-line-height-150);
  --sb-text-body-md-tracking: var(--sb-tracking-none);

  /* body/sm — Archivo Regular 14 / 1.45 / 0 (same on mobile) */
  --sb-text-body-sm-family: var(--sb-font-family-sans);
  --sb-text-body-sm-weight: var(--sb-font-weight-regular);
  --sb-text-body-sm-width: var(--sb-font-width-normal);
  --sb-text-body-sm-size: var(--sb-font-size-14);
  --sb-text-body-sm-line-height: var(--sb-line-height-145);
  --sb-text-body-sm-tracking: var(--sb-tracking-none);

  /* label/lg — Archivo SemiBold 16 / 1.2 / 0 (same on mobile) */
  --sb-text-label-lg-family: var(--sb-font-family-sans);
  --sb-text-label-lg-weight: var(--sb-font-weight-semibold);
  --sb-text-label-lg-width: var(--sb-font-width-normal);
  --sb-text-label-lg-size: var(--sb-font-size-16);
  --sb-text-label-lg-line-height: var(--sb-line-height-120);
  --sb-text-label-lg-tracking: var(--sb-tracking-none);

  /* label/md — Archivo SemiBold 14 / 1.2 / 0 (same on mobile) */
  --sb-text-label-md-family: var(--sb-font-family-sans);
  --sb-text-label-md-weight: var(--sb-font-weight-semibold);
  --sb-text-label-md-width: var(--sb-font-width-normal);
  --sb-text-label-md-size: var(--sb-font-size-14);
  --sb-text-label-md-line-height: var(--sb-line-height-120);
  --sb-text-label-md-tracking: var(--sb-tracking-none);

  /* label/sm — Archivo SemiBold 12 / 1.2 / 0 (same on mobile) */
  --sb-text-label-sm-family: var(--sb-font-family-sans);
  --sb-text-label-sm-weight: var(--sb-font-weight-semibold);
  --sb-text-label-sm-width: var(--sb-font-width-normal);
  --sb-text-label-sm-size: var(--sb-font-size-12);
  --sb-text-label-sm-line-height: var(--sb-line-height-120);
  --sb-text-label-sm-tracking: var(--sb-tracking-none);

  /* mono/overline — JetBrains Mono Bold 12 / 1.2 / 0.08em, UPPERCASE
     (no width token: JetBrains Mono has no wdth axis) */
  --sb-text-mono-overline-family: var(--sb-font-family-mono);
  --sb-text-mono-overline-weight: var(--sb-font-weight-bold);
  --sb-text-mono-overline-size: var(--sb-font-size-12);
  --sb-text-mono-overline-line-height: var(--sb-line-height-120);
  --sb-text-mono-overline-tracking: var(--sb-tracking-wide);
  --sb-text-mono-overline-transform: uppercase;

  /* mono/md — JetBrains Mono Regular 14 / 1.5 / 0 */
  --sb-text-mono-md-family: var(--sb-font-family-mono);
  --sb-text-mono-md-weight: var(--sb-font-weight-regular);
  --sb-text-mono-md-size: var(--sb-font-size-14);
  --sb-text-mono-md-line-height: var(--sb-line-height-150);
  --sb-text-mono-md-tracking: var(--sb-tracking-none);

  /* mono/sm — JetBrains Mono Regular 12 / 1.5 / 0 */
  --sb-text-mono-sm-family: var(--sb-font-family-mono);
  --sb-text-mono-sm-weight: var(--sb-font-weight-regular);
  --sb-text-mono-sm-size: var(--sb-font-size-12);
  --sb-text-mono-sm-line-height: var(--sb-line-height-150);
  --sb-text-mono-sm-tracking: var(--sb-tracking-none);

  /* ---------- Semantic color · Light (default mode) ---------- */
  --sb-bg-canvas: var(--sb-gray-50);
  --sb-bg-surface: var(--sb-white);
  --sb-bg-surface-raised: var(--sb-white);
  --sb-bg-muted: var(--sb-gray-100);
  --sb-bg-muted-hover: var(--sb-gray-200);
  --sb-bg-inverse: var(--sb-black);
  --sb-bg-inverse-hover: var(--sb-gray-800);
  --sb-bg-inverse-active: var(--sb-gray-700);
  --sb-bg-hover: var(--sb-alpha-black-5);
  --sb-bg-active: var(--sb-alpha-black-10);
  --sb-bg-accent: var(--sb-orange-500);
  --sb-bg-accent-hover: var(--sb-orange-600);
  --sb-bg-accent-active: var(--sb-orange-700);
  --sb-bg-accent-subtle: var(--sb-orange-100);
  --sb-bg-danger: var(--sb-red-500);
  --sb-bg-danger-hover: var(--sb-red-700);
  --sb-bg-danger-active: var(--sb-red-900);
  --sb-bg-danger-subtle: var(--sb-red-100);
  --sb-bg-success: var(--sb-green-500);
  --sb-bg-success-subtle: var(--sb-green-100);
  --sb-bg-warning: var(--sb-yellow-500);
  --sb-bg-warning-subtle: var(--sb-yellow-100);
  --sb-bg-info: var(--sb-blue-500);
  --sb-bg-info-subtle: var(--sb-blue-100);
  --sb-bg-disabled: var(--sb-gray-200);
  --sb-bg-overlay: var(--sb-alpha-black-60);

  --sb-text-primary: var(--sb-black);
  --sb-text-secondary: var(--sb-gray-700);
  --sb-text-muted: var(--sb-gray-600);
  /* Placeholder holds one rung below muted. Clears AA on canvas, surface and
     surface-raised (4.54:1 / 4.74:1 / 4.74:1) and misses on bg/muted at
     4.31:1. No rung fixes that: the lightest grey clearing 4.5:1 there is
     #707070, and the next one down is text/muted itself. Known and kept. */
  --sb-text-placeholder: var(--sb-gray-500);
  --sb-text-inverse: var(--sb-white);
  --sb-text-accent: var(--sb-orange-700);
  --sb-text-on-accent: var(--sb-black);
  --sb-text-danger: var(--sb-red-700);
  --sb-text-success: var(--sb-green-700);
  --sb-text-warning: var(--sb-yellow-700);
  --sb-text-info: var(--sb-blue-700);
  --sb-text-disabled: var(--sb-gray-400);

  --sb-border-default: var(--sb-black);
  --sb-border-muted: var(--sb-gray-300);
  --sb-border-accent: var(--sb-orange-500);
  --sb-border-danger: var(--sb-red-500);
  --sb-border-focus: var(--sb-orange-500);
  --sb-border-disabled: var(--sb-gray-300);

  /* icon/* alias text/* in both modes — no dark overrides needed;
     they re-resolve automatically when the text vars flip */
  --sb-icon-default: var(--sb-text-primary);
  --sb-icon-secondary: var(--sb-text-secondary);
  --sb-icon-muted: var(--sb-text-muted);
  --sb-icon-inverse: var(--sb-text-inverse);
  --sb-icon-accent: var(--sb-text-accent);
  --sb-icon-on-accent: var(--sb-text-on-accent);
  --sb-icon-danger: var(--sb-text-danger);
  --sb-icon-success: var(--sb-text-success);
  --sb-icon-warning: var(--sb-text-warning);
  --sb-icon-info: var(--sb-text-info);
  --sb-icon-disabled: var(--sb-text-disabled);

  --sb-shadow-color: var(--sb-black);
}

/* ---------- Text styles · Mobile mode ----------
   Figma: Text collection, Mobile mode. Only sizes change, and
   only for display and heading. Line-height (unitless) and
   tracking (em) scale with the size automatically, so they are
   not repeated here — the Figma per-mode px values resolve to
   the same ratios. Width is unchanged; see the header note. */
@media (max-width: 767px) {
  :root {
    --sb-text-display-1-size: var(--sb-font-size-56);
    --sb-text-display-2-size: var(--sb-font-size-44);
    --sb-text-display-3-size: var(--sb-font-size-32);
    --sb-text-heading-1-size: var(--sb-font-size-28);
    --sb-text-heading-2-size: var(--sb-font-size-24);
    --sb-text-heading-3-size: var(--sb-font-size-20);
    --sb-text-heading-4-size: var(--sb-font-size-18);
  }
}

/* ---------- Semantic color · Dark mode overrides ---------- */
[data-theme="dark"] {
  --sb-bg-canvas: var(--sb-black);
  --sb-bg-surface: var(--sb-gray-950);
  --sb-bg-surface-raised: var(--sb-gray-900);
  --sb-bg-muted: var(--sb-gray-800);
  --sb-bg-muted-hover: var(--sb-gray-700);
  --sb-bg-inverse: var(--sb-white);
  --sb-bg-inverse-hover: var(--sb-gray-200);
  --sb-bg-inverse-active: var(--sb-gray-300);
  --sb-bg-hover: var(--sb-alpha-white-10);
  --sb-bg-active: var(--sb-alpha-white-20);
  --sb-bg-accent-hover: var(--sb-orange-400);
  --sb-bg-accent-active: var(--sb-orange-300);
  --sb-bg-accent-subtle: var(--sb-orange-900);
  --sb-bg-danger-hover: var(--sb-red-300);
  --sb-bg-danger-active: var(--sb-red-100);
  --sb-bg-danger-subtle: var(--sb-red-900);
  --sb-bg-success-subtle: var(--sb-green-900);
  --sb-bg-warning-subtle: var(--sb-yellow-900);
  --sb-bg-info-subtle: var(--sb-blue-900);
  --sb-bg-disabled: var(--sb-gray-800);

  --sb-text-primary: var(--sb-white);
  --sb-text-secondary: var(--sb-gray-300);
  /* muted is overridden here because the light-mode value fails WCAG AA on
     every dark ground. gray-400 clears all four (6.00:1 on bg/muted up to
     8.33:1 on bg/canvas); secondary sits at gray-300 so the ramp descends in
     lightness the way the light ramp does. icon/muted and icon/secondary
     alias their text counterparts and follow without overrides of their own. */
  --sb-text-muted: var(--sb-gray-400);
  /* Placeholder holds one rung below muted, as in light. It does not meet AA
     on any dark ground — 3.19:1 on bg/muted up to 4.43:1 on bg/canvas. The
     scale has no rung between gray-400 (which is text/muted) and gray-500,
     so keeping placeholder distinct from muted costs the contrast. Known and
     kept; revisit by adding a rung near #8c8c8c if it ever matters. */
  --sb-text-placeholder: var(--sb-gray-500);
  --sb-text-inverse: var(--sb-black);
  --sb-text-accent: var(--sb-orange-400);
  --sb-text-danger: var(--sb-red-300);
  --sb-text-success: var(--sb-green-300);
  --sb-text-warning: var(--sb-yellow-300);
  --sb-text-info: var(--sb-blue-300);
  --sb-text-disabled: var(--sb-gray-600);

  --sb-border-default: var(--sb-white);
  --sb-border-muted: var(--sb-gray-700);
  --sb-border-danger: var(--sb-red-300);
  --sb-border-focus: var(--sb-orange-400);
  --sb-border-disabled: var(--sb-gray-700);

  --sb-shadow-color: var(--sb-white);
}
